/*
 * A325422  Complement of A077477.
 * https://oeis.org/A325422
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = nth smallest integer of the form 2x+1 or 3x+1, where x
 *            ranges over the complement sequence A077477. The sequence is
 *            generated by iterating over all positive integers, skipping
 *            those already marked as “covered”, marking the images 2*x+1 and
 *            3*x+1 as covered, and collecting those images in t...
 * Range:     u8 n <= 99, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   extend_covered, extend_seq
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/extend_covered.h"
#include "../utils/extend_seq.h"

/* the sequence function requested */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;          /* safety, unused */

    /* static state retained between calls */
    static bool *covered      = NULL;
    static size_t covered_cap = 0;
    static seq_t *out2 = NULL;  /* values of 2*x+1 */
    static seq_t *out3 = NULL;  /* values of 3*x+1 */
    static size_t out2_len = 0, out2_cap = 0;
    static size_t out3_len = 0, out3_cap = 0;
    static idx_t next_x = 1;    /* next candidate integer to test */

    /* generate enough elements so that the two lists contain at least
       2*n values in total (enough to obtain n distinct terms). */
    while ((out2_len + out3_len) < 2 * n)
    {
        /* ensure the covered array can index into next_x */
        extend_covered(next_x, &covered, &covered_cap);

        if (!covered[next_x])                 /* new member of the
                                                  complement sequence   */
        {
            /* produce 2*x+1 and 3*x+1 */
            seq_t v1 = ((seq_t)next_x) * 2 + 1;
            seq_t v2 = ((seq_t)next_x) * 3 + 1;

            /* store the outputs in ascending order */
            extend_seq(out2_len + 1, &out2, &out2_cap);
            out2[out2_len++] = v1;

            extend_seq(out3_len + 1, &out3, &out3_cap);
            out3[out3_len++] = v2;

            /* mark the images as covered */
            idx_t idx1 = ((idx_t)2 * next_x) + 1;
            idx_t idx2 = ((idx_t)3 * next_x) + 1;

            extend_covered(idx1, &covered, &covered_cap);
            covered[idx1] = true;

            extend_covered(idx2, &covered, &covered_cap);
            covered[idx2] = true;
        }

        ++next_x;            /* move to the next candidate integer */
    }

    /* merge the two sorted lists, removing duplicates,
       until the n-th term is found. */
    size_t i2 = 0, i3 = 0;
    size_t cnt = 0;
    seq_t last = 0;
    bool have_last = false;
    seq_t result = 0;

    while (cnt < n)
    {
        bool has2 = (i2 < out2_len);
        bool has3 = (i3 < out3_len);
        seq_t val;

        if (has2 && has3) {
            if (out2[i2] < out3[i3]) { val = out2[i2]; ++i2; }
            else if (out3[i3] < out2[i2]) { val = out3[i3]; ++i3; }
            else { val = out2[i2]; ++i2; ++i3; } /* equal, skip duplicate later */
        } else if (has2) { val = out2[i2]; ++i2; }
        else { val = out3[i3]; ++i3; }

        if (!have_last || val != last) {
            result = val;
            last = val;
            have_last = true;
            ++cnt;
        }
    }

    return result;
}
